  if not found then insert into public.questions (lesson_id, prompt, option_a, option_b, option_c, option_d, correct_option, explanation, position) values (v_lesson_id, 'Welche Aussage passt am besten zu «Lernbereiche»?', 'Sprache und Gesellschaft verbinden; Alltagssituationen bearbeiten', 'Nur Grammatik üben; Gesellschaft ausblenden, anhand klarer Kriterien', 'Nur Tests lösen; Transfer vermeiden, mit Blick auf die Folgen', 'Einzelwissen sammeln; Zusammenhänge trennen, bei Bedarf im Team', 'A', 'ABU verbindet Sprache, Kommunikation und Gesellschaft in lebensnahen Situationen.', 1); end if;
