do $$
declare
  v_module_id uuid;
  v_lesson_id uuid;
begin

  -- Modul STB_HK1: Strassenbauarbeiten vorbereiten und ausführen
  select id into v_module_id from public.modules where course_key = 'strassenbau' and title in ('Strassenbauarbeiten vorbereiten und ausführen', 'HK1 – Strassenbauarbeiten vorbereiten und ausführen') order by case when title = 'Strassenbauarbeiten vorbereiten und ausführen' then 0 else 1 end limit 1;
  if v_module_id is null then
    insert into public.modules (title, description, course_key, position)
    values ('Strassenbauarbeiten vorbereiten und ausführen', 'Handlungskompetenzbereich 1: Arbeitssicherheit, Arbeitsvorbereitung, Umweltschutz, Ausmass/Rapport und Maschineneinsatz.', 'strassenbau', 10)
    returning id into v_module_id;
  else
    update public.modules set title = 'Strassenbauarbeiten vorbereiten und ausführen', description = 'Handlungskompetenzbereich 1: Arbeitssicherheit, Arbeitsvorbereitung, Umweltschutz, Ausmass/Rapport und Maschineneinsatz.', position = 10 where id = v_module_id;
  end if;

  -- Lektion (pos 10): Arbeitssicherheit und Notfall
  select id into v_lesson_id from public.lessons where module_id = v_module_id and (title = 'Arbeitssicherheit und Notfall' or title ~ ('^[0-9]+\.[0-9]+ ' || 'Arbeitssicherheit und Notfall')) order by case when title = 'Arbeitssicherheit und Notfall' then 0 else 1 end limit 1;
  if v_lesson_id is null then
    insert into public.lessons (module_id, title, position, pass_score)
    values (v_module_id, 'Arbeitssicherheit und Notfall', 10, 70)
    returning id into v_lesson_id;
  else
    update public.lessons set title = 'Arbeitssicherheit und Notfall', position = 10, pass_score = 70 where id = v_lesson_id;
  end if;
  update public.questions set prompt = 'Welche Aussage passt am besten zu «PSA»?', option_a = 'PSA vollständig tragen; Zustand prüfen', option_b = 'Helm später holen; Risiko akzeptieren', option_c = 'Warnkleidung weglassen; Sichtbarkeit senken', option_d = 'Schuhe frei wählen; Schutzwirkung mindern', correct_option = 'A', explanation = 'PSA schützt nur, wenn sie vollständig, passend und intakt getragen wird.' where lesson_id = v_lesson_id and position = 1;
  if not found then insert into public.questions (lesson_id, prompt, option_a, option_b, option_c, option_d, correct_option, explanation, position) values (v_lesson_id, 'Welche Aussage passt am besten zu «PSA»?', 'PSA vollständig tragen; Zustand prüfen', 'Helm später holen; Risiko akzeptieren', 'Warnkleidung weglassen; Sichtbarkeit senken', 'Schuhe frei wählen; Schutzwirkung mindern', 'A', 'PSA schützt nur, wenn sie vollständig, passend und intakt getragen wird.', 1); end if;
